 {"id": "PEDS-C4-051", "sec": "TTNB", "page": 17, "q": "Management of TTNB is ___", "opts": ["Surfactant", "Emergency surgery", "Antibiotics", "Supportive (O2 inhalation) - sufficient as it is a transient condition"], "ans": 3, "exp": "Supportive management (O2 inhalation) is sufficient as it is a transient condition. (Book p17)", "type": "fill"},
 {"id": "PEDS-C4-052", "sec": "TTNB", "page": 17, "q": "Improvement in TTNB is seen in ___", "opts": ["48-72 hours", "1 year", "2-3 weeks", "1-2 hours"], "ans": 0, "exp": "Improvement seen in 48-72 hours. (Book p17)", "type": "fill"},
 {"id": "PEDS-C4-053", "sec": "RDS", "page": 17, "q": "RDS is also called ___", "opts": ["Wet lung syndrome", "Hyaline membrane disease", "Atelectasis", "Meconium lung"], "ans": 1, "exp": "AKA hyaline membrane disease (HMD). (Book p17)", "type": "fill"},
 {"id": "PEDS-C4-054", "sec": "RDS", "page": 17, "q": "RDS is m/c seen in preterm babies of ___", "opts": ["> 36 weeks", "< 37 weeks", "< 34 weeks", "< 28 weeks only"], "ans": 2, "exp": "Preterm babies (<34 weeks). (Book p17)", "type": "fill"},
 {"id": "PEDS-C4-055", "sec": "RDS", "page": 17, "q": "RDS is m/c in preterm babies born to mothers who ___", "opts": ["Were well nourished", "Had normal labour", "Received antenatal steroids", "Haven't received antenatal steroids"], "ans": 3, "exp": "Born to mothers who haven't received antenatal steroids. (Book p17)", "type": "fill"},
 {"id": "PEDS-C4-056", "sec": "RDS", "page": 17, "q": "The m/c antenatal steroid used for RDS prevention is ___", "opts": ["Dexamethasone", "Betamethasone only", "Oxytocin", "Ergometrine"], "ans": 0, "exp": "m/c: dexamethasone. (Book p17)", "type": "fill"},
 {"id": "PEDS-C4-057", "sec": "RDS", "page": 17, "q": "RDS is also m/c seen in term healthy babies.", "opts": ["True", "False"], "ans": 1, "exp": "False — correct: Infants of diabetic mothers. Infants of diabetic mothers (IDM). (Book p17)", "type": "tf"},
 {"id": "PEDS-C4-058", "sec": "RDS", "page": 18, "q": "In infants of diabetic mothers, RDS occurs via ___", "opts": ["Excess surfactant", "Down insulin -> up surfactant", "Up insulin -> down surfactant", "Low glucose"], "ans": 2, "exp": "Infants of diabetic mother -> up insulin -> down surfactant. (Book p18)", "type": "fill"},
 {"id": "PEDS-C4-059", "sec": "RDS", "page": 18, "q": "RDS pathogenesis: down surfactant leads to ___", "opts": ["Alveolar expansion", "Better ventilation", "Down surface tension", "Up surface tension"], "ans": 3, "exp": "Down surfactant -> up surface tension -> alveolar collapse and respiratory distress. (Book p18)", "type": "fill"},
 {"id": "PEDS-C4-060", "sec": "RDS", "page": 18, "q": "Surfactant keeps alveoli open by ___", "opts": ["Decreasing surface tension on its lining", "Contracting muscle", "Increasing surface tension", "Adding volume"], "ans": 0, "exp": "Surfactant keeps alveoli open by decreasing surface tension on its lining. (Book p18)", "type": "fill"},
 {"id": "PEDS-C4-061", "sec": "RDS", "page": 18, "q": "Histology of RDS shows eosinophilic substances in lung tissue.", "opts": ["True", "False"], "ans": 0, "exp": "True — Histology: eosinophilic substances in lung tissue (resembles hyaline). (Book p18)", "type": "tf"},
 {"id": "PEDS-C4-062", "sec": "RDS", "page": 18, "q": "Chest X-ray of RDS shows ___", "opts": ["Air in the wall", "Decreasing surface tension on its lining", "White out appearance / ground glass appearance", "Sunburst appearance"], "ans": 2, "exp": "White out appearance/ground glass appearance: d/t collapsed alveoli -> no air entry. (Book p18) (collapsed alveoli, no air entry)", "type": "fill"},
 {"id": "PEDS-C4-063", "sec": "RDS", "page": 18, "q": "The air bronchogram sign in RDS is due to ___", "opts": ["Collapsed airways", "Fluid in pleura", "Meconium", "Open airway tract"], "ans": 3, "exp": "Air bronchogram sign: d/t open airway tract. (Book p18)", "type": "fill"},
 {"id": "PEDS-C4-064", "sec": "Management (RDS)", "page": 18, "q": "Severity of RDS is assessed based on ___", "opts": ["Silverman score", "Downe's score", "Weight", "APGAR alone"], "ans": 0, "exp": "Severity assessed based on Silverman score. (Book p18)", "type": "fill"},
 {"id": "PEDS-C4-065", "sec": "Management (RDS)", "page": 18, "q": "Mild (<5) and moderate (5-7) RDS is managed with ___", "opts": ["Surfactant only", "Continuous positive airway pressure", "Intubation, Surfactant, Extubation", "Mechanical ventilation"], "ans": 1, "exp": "Mild (<5), moderate (5-7) -> CPAP. (Book p18)", "type": "fill"},
 {"id": "PEDS-C4-066", "sec": "Management (RDS)", "page": 18, "q": "In CPAP for RDS, the PEEP maintained is ___", "opts": ["1-2 mm of H2O", "15-20 mm of H2O", "5-7 mm of H2O", "30 mm of H2O"], "ans": 2, "exp": "PEEP of 5-7 mm of H2O maintained. (Book p18)", "type": "fill"},
 {"id": "PEDS-C4-067", "sec": "Management (RDS)", "page": 18, "q": "CPAP in RDS works by ___", "opts": ["Stimulating cry", "Cooling the baby", "Increasing blood pressure", "Keeping alveoli open"], "ans": 3, "exp": "CPAP -> keeps alveoli open. (Book p18)", "type": "fill"},
 {"id": "PEDS-C4-068", "sec": "Management (RDS)", "page": 18, "q": "Severe (>7) RDS is managed with observation.", "opts": ["True", "False"], "ans": 1, "exp": "False — correct: Mechanical ventilation. Severe (>7) -> mechanical ventilation. (Book p18)", "type": "tf"},
